_PATTERN = re.compile(
    r"\s*(?:(\d+)d)?(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?\s*"
)


def parse_duration(s):
    """Convert a duration string such as '1h30m' into an int number of seconds.

    Units must be d, h, m, s, each appearing at most once and in that order.
    Each amount is a non-negative integer. Surrounding whitespace is allowed.
    Invalid input raises ValueError.
    """
    if not isinstance(s, str):
        raise ValueError("duration must be a string")

    match = _PATTERN.fullmatch(s)
    if match is None:
        raise ValueError(f"invalid duration: {s!r}")

    days, hours, minutes, seconds = match.groups()
    if all(part is None for part in (days, hours, minutes, seconds)):
        raise ValueError(f"invalid duration: {s!r}")

    multipliers = (86400, 3600, 60, 1)
    total = 0
    for amount, multiplier in zip((days, hours, minutes, seconds), multipliers):
        if amount is not None:
            total += int(amount) * multiplier

    return total
